mapper.update:
UPDATE manga_agent_state
SET state_kind = #{stateKind},
    state_type = #{stateType},
    state_json = #{stateJson},
    state_version = state_version + 1,
    updated_by = #{updatedBy}
WHERE user_key = #{userKey}
  AND state_session_id = #{stateSessionId}
  AND state_key = #{stateKey}
  AND state_version = #{stateVersion}

mapper.select:
SELECT COUNT(*)
FROM manga_agent_state
WHERE user_key = #{userKey}
  AND state_session_id = #{stateSessionId}

mapper.delete:
DELETE FROM manga_agent_state
WHERE user_key = #{userKey}
  AND state_session_id = #{stateSessionId}

